@@ -4,6 +4,9 @@ set -u
 . "$(dirname "$0")/lib/slots.sh"
 BOOKINGS=${BOOKINGS:-data/bookings.tsv}
 room=$1 date=$2 start=$3 end=$4 who=$5
+if ! [[ "$date" =~ ^[0-9]{4}-[0-9]{2}-[0-9]{2}$ ]]; then echo "invalid date: $date" >&2; exit 2; fi
+mon=$(printf '%d' "${date:5:2}" 2>/dev/null) && day=$(printf '%d' "${date:8:2}" 2>/dev/null) || { echo "invalid date: $date" >&2; exit 2; }
+[ "$mon" -ge 1 ] && [ "$mon" -le 12 ] && [ "$day" -ge 1 ] && [ "$day" -le 31 ] || { echo "invalid date: $date" >&2; exit 2; }
 s=$(to_min "$start"); e=$(to_min "$end")
 [ "$s" -lt "$e" ] || { echo "end must be after start" >&2; exit 2; }
 while IFS=$'\t' read -r r d bs be bw; do
== spec file
     1	#!/bin/bash
     2	fail=0
     3	t=$(mktemp); printf '# h\n' > "$t"
     4	b() { BOOKINGS=$t bash src/book.sh "$@" >/dev/null 2>&1; }
     5	b aoi 2026/12/01 10:00 11:00 x; [ $? = 2 ] || { echo "slashes should exit 2"; fail=1; }
     6	b aoi 2026-12-08 10:00 11:00 x || { echo "the 8th was rejected"; fail=1; }
     7	b kaede 2026-09-15 10:00 11:00 x || { echo "September was rejected"; fail=1; }
     8	b aoi 2026-00-10 10:00 11:00 x; [ $? = 2 ] || { echo "month 00 should exit 2"; fail=1; }
     9	rm -f "$t"; exit $fail
== develop book.sh
BOOKINGS=${BOOKINGS:-data/bookings.tsv}
room=$1 date=$2 start=$3 end=$4 who=$5
s=$(to_min "$start"); e=$(to_min "$end")
[ "$s" -lt "$e" ] || { echo "end must be after start" >&2; exit 2; }
while IFS=$'\t' read -r r d bs be bw; do
== lint
     1	#!/bin/bash
     2	# lint: every script parses (bash -n), no line ends with whitespace, and src/*.sh declare set -u. Usage: bash tools/lint
     3	s=0
     4	for f in src/*.sh src/lib/*.sh tools/* spec/*.spec.sh; do
     5	  bash -n "$f" 2>/dev/null || { echo "LINT $f: syntax error"; s=1; }
     6	  if grep -qE '[[:space:]]+$' "$f"; then echo "LINT $f: trailing whitespace"; s=1; fi
     7	done
     8	for f in src/*.sh; do grep -q '^set -u' "$f" || { echo "LINT $f: missing set -u"; s=1; }; done
     9	[ $s = 0 ] || exit 1
    10	echo "lint ok"
